#!/usr/bin/env node
/**
 * Generates the typed API client's types from the backend's OpenAPI document.
 *
 *   npm run api:generate                         from the committed snapshot (src/api/openapi.json)
 *   npm run api:generate -- --url <url>          fetch the document first and update the snapshot
 *   STEMN_OPENAPI_URL=<url> npm run api:generate  same, the url from the environment
 *   npm run api:check                            fail if the generated files are not what the snapshot gives
 *   npm run api:check -- --url <url>             also fail if the served document differs from the snapshot
 *
 * The live dev API serves the document at http://localhost:3000/api/v1/openapi.json (`--url local`).
 * Outputs (all in stemn-frontend-shared/src/api, formatted with Prettier):
 *   openapi.json        the document as the backend serves it (only written when fetched)
 *   schema.gen.ts       openapi-typescript output: paths, components, operations
 *   operations.gen.ts   per-operation aliases (<OperationId>Response / Body / Query / Path) and apiOperations
 * The overrides in ./overrides.mjs correct known mismatches of the document first (see docs/API-CLIENT.md).
 */
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseArgs } from 'node:util'
import openapiTS, { astToString } from 'openapi-typescript'
import * as prettier from 'prettier'
import { applyOverrides } from './overrides.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const apiDir = join(here, '../../src/api')
const repoRoot = join(here, '../../..')
const files = {
  snapshot: join(apiDir, 'openapi.json'),
  schema: join(apiDir, 'schema.gen.ts'),
  operations: join(apiDir, 'operations.gen.ts'),
}
const LOCAL_URL = 'http://localhost:3000/api/v1/openapi.json'
const METHODS = ['get', 'put', 'post', 'delete', 'patch']

const { values: args } = parseArgs({
  options: { url: { type: 'string' }, check: { type: 'boolean', default: false } },
})
const url = args.url === 'local' ? LOCAL_URL : args.url || process.env.STEMN_OPENAPI_URL

const format = async (file, text) => prettier.format(text, { ...(await prettier.resolveConfig(file)), filepath: file })

const banner = (source) =>
  `// Generated by \`npm run api:generate\` (stemn-frontend-shared/scripts/api-client) from ${source}.\n` +
  '// Do not edit: change the backend types, or the overrides in scripts/api-client/overrides.mjs.\n'

const fetchDocument = async (from) => {
  const response = await fetch(from, { headers: { accept: 'application/json' } })
  if (!response.ok) throw new Error(`GET ${from}: ${response.status} ${response.statusText}`)
  const document = await response.json()
  if (!String(document.openapi || '').startsWith('3.')) throw new Error(`${from} is not an OpenAPI 3 document`)
  return document
}

const operationsModule = (spec) => {
  const ops = []
  for (const [path, item] of Object.entries(spec.paths)) {
    for (const method of METHODS) {
      const op = item[method]
      if (!op) continue
      const params = [...(item.parameters || []), ...(op.parameters || [])]
      const has200Json = Boolean(op.responses && op.responses['200'] && op.responses['200'].content)
      ops.push({
        id: op.operationId,
        method,
        path,
        body: Boolean(op.requestBody && op.requestBody.content && op.requestBody.content['application/json']),
        query: params.some((param) => param.in === 'query'),
        pathParams: params.some((param) => param.in === 'path'),
        response: has200Json,
      })
    }
  }
  ops.sort((a, b) => a.id.localeCompare(b.id))
  const duplicate = ops.find((op, index) => index > 0 && ops[index - 1].id === op.id)
  if (duplicate) throw new Error(`operationId ${duplicate.id} is used twice`)

  const lines = [
    banner('src/api/openapi.json'),
    "import type { ApiPathParams, ApiQuery, ApiRequestBody, ApiResponse } from './types'",
    '',
    '/** Every operation of the API by operationId: method and path (the MSW test handlers use it) */',
    'export const apiOperations = {',
    ...ops.map((op) => `  ${op.id}: { method: '${op.method}', path: '${op.path}' },`),
    '} as const',
    '',
    'export type ApiOperations = typeof apiOperations',
    '',
  ]
  for (const op of ops) {
    lines.push(`/** ${op.method.toUpperCase()} ${op.path} */`)
    lines.push(`export type ${op.id}Response = ApiResponse<'${op.id}'>`)
    if (op.body) lines.push(`export type ${op.id}Body = ApiRequestBody<'${op.id}'>`)
    if (op.query) lines.push(`export type ${op.id}Query = ApiQuery<'${op.id}'>`)
    if (op.pathParams) lines.push(`export type ${op.id}Path = ApiPathParams<'${op.id}'>`)
  }
  return `${lines.join('\n')}\n`
}

const main = async () => {
  const snapshotText = await readFile(files.snapshot, 'utf8').catch(() => undefined)
  let document = snapshotText && JSON.parse(snapshotText)
  const outputs = {}

  if (url) {
    console.log(`api: fetching ${url}`)
    const fetched = await fetchDocument(url)
    const fetchedText = await format(files.snapshot, JSON.stringify(fetched))
    if (args.check) {
      if (fetchedText !== snapshotText) {
        throw new Error(
          `the document served at ${url} differs from src/api/openapi.json: run \`npm run api:generate -- --url ${args.url || url}\``,
        )
      }
    } else {
      outputs.snapshot = fetchedText
    }
    document = fetched
  }
  if (!document) throw new Error('no src/api/openapi.json snapshot yet: run with --url to fetch the document')

  const { spec, stale } = applyOverrides(document)
  stale.forEach((id) =>
    console.warn(`api: override "${id}" no longer changes the document (fixed in the backend?): delete it`),
  )

  const ast = await openapiTS(spec, { alphabetize: false, exportType: false })
  outputs.schema = await format(files.schema, `${banner('src/api/openapi.json')}\n${astToString(ast)}`)
  outputs.operations = await format(files.operations, operationsModule(spec))

  const outdated = []
  for (const [key, text] of Object.entries(outputs)) {
    const file = files[key]
    const current = await readFile(file, 'utf8').catch(() => undefined)
    if (current === text) continue
    if (args.check) outdated.push(relative(repoRoot, file))
    else {
      await writeFile(file, text)
      console.log(`api: wrote ${relative(repoRoot, file)}`)
    }
  }
  if (outdated.length) {
    throw new Error(`generated files are out of date: ${outdated.join(', ')}. Run \`npm run api:generate\`.`)
  }
  const count = Object.values(spec.paths).reduce((n, item) => n + METHODS.filter((m) => item[m]).length, 0)
  console.log(
    `api: ${args.check ? 'up to date' : 'generated'} (${count} operations, OpenAPI ${spec.openapi}, API ${spec.info.version})`,
  )
}

main().catch((error) => {
  console.error(`api: ${error.message}`)
  process.exit(1)
})
